"""46 template Kuantitatif deterministik mencakup 13 topik MAT-* (Level 1-3)."""
from fractions import Fraction
import math


def _pick(correct_val, cands, fmt):
    out, seen = [], {correct_val}
    for v in cands:
        if v is not None and v not in seen:
            out.append(fmt(v))
            seen.add(v)
        if len(out) == 3:
            break
    k = 1
    while len(out) < 3:
        cand = correct_val + k if isinstance(correct_val, (int, Fraction)) else None
        if cand is not None and cand not in seen:
            out.append(fmt(cand))
            seen.add(cand)
        k += 1
    return out


def _pick_pos(correct_val, cands, fmt):
    filtered = [v for v in cands if v is not None and v > 0]
    return _pick(correct_val, filtered, fmt)


# --- MAT-PEC (4) ---
def mat_01_pec_tambah_sama(rng):
    d = rng.choice([6, 8, 10, 12]); a = rng.randint(1, d // 2 - 1); b = rng.randint(1, d // 2 - 1)
    s = Fraction(a + b, d); f = lambda v: f"{v.numerator}/{v.denominator}"
    cands = [Fraction(a + b, 2 * d), Fraction(a + b + 1, d), Fraction(a + b, d + 1), Fraction(a + b + 2, d), Fraction(abs(a - b) or 1, d)]
    return {"topic": "MAT-PEC", "subtopic": "Penjumlahan pecahan penyebut sama", "level": 1,
            "stem": f"Hitung bentuk paling sederhana dari {a}/{d} + {b}/{d}!",
            "correct": f(s), "distractors": _pick_pos(s, cands, f),
            "explanation": "Karena penyebut sama, jumlahkan pembilangnya lalu sederhanakan pecahan.",
            "shortcut": "Penyebut sama: jumlahkan atas saja, lalu sederhanakan."}


def mat_02_pec_beda_penyebut(rng):
    d1, d2 = rng.choice([(2, 3), (3, 4), (2, 5), (3, 5), (4, 5)])
    a = rng.randint(1, d1 - 1); b = rng.randint(1, d2 - 1)
    s = Fraction(a, d1) + Fraction(b, d2); f = lambda v: f"{v.numerator}/{v.denominator}"
    cands = [Fraction(a + b, d1 + d2), s + Fraction(1, d1 * d2), abs(Fraction(a, d1) - Fraction(b, d2)) or Fraction(1, d1 * d2), s + Fraction(2, d1 * d2), Fraction(a * b, d1 * d2)]
    return {"topic": "MAT-PEC", "subtopic": "Penjumlahan pecahan beda penyebut", "level": 2,
            "stem": f"Hasil paling sederhana dari {a}/{d1} + {b}/{d2} adalah ...",
            "correct": f(s), "distractors": _pick_pos(s, cands, f),
            "explanation": "Samakan penyebut memakai KPK penyebut terlebih dahulu sebelum menjumlahkan pembilang.",
            "shortcut": "Kali silang pembilang: (a*d2 + b*d1) / (d1*d2), lalu sederhanakan."}


def mat_03_pec_kurang(rng):
    d = rng.choice([8, 10, 12]); a = rng.randint(d // 2 + 1, d - 1); b = rng.randint(1, d // 2 - 1)
    s = Fraction(a - b, d); f = lambda v: f"{v.numerator}/{v.denominator}"
    cands = [Fraction(a + b, d), Fraction(a - b + 1, d), Fraction(a - b, d + 1), Fraction(a - b + 2, d), Fraction(b, d)]
    return {"topic": "MAT-PEC", "subtopic": "Pengurangan pecahan", "level": 1,
            "stem": f"Sisa pita sepanjang {a}/{d} m setelah dipotong {b}/{d} m adalah ... m.",
            "correct": f(s), "distractors": _pick_pos(s, cands, f),
            "explanation": "Kurangkan pembilang karena penyebut sudah sama, kemudian sederhanakan hasilnya.",
            "shortcut": "Penyebut sama: langsung kurangkan pembilang atasnya."}


def mat_04_pec_kali_bilangan(rng):
    d = rng.choice([4, 5, 6]); num = rng.randint(1, d - 1); k = rng.choice([2, 3, 4]) * d
    ans = num * k // d
    cands = [ans + d, max(1, ans - 2), ans + 3, num * k, ans + 5]
    return {"topic": "MAT-PEC", "subtopic": "Pecahan dari bilangan bulat", "level": 2,
            "stem": f"Nilai dari {num}/{d} bagian dari {k} butir kelereng adalah ... butir.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Bagi bilangan total dengan penyebut terlebih dahulu, lalu kalikan dengan pembilang.",
            "shortcut": "Bagi dulu dengan penyebut agar angkanya kecil, baru kalikan pembilang."}


# --- MAT-KPK (4) ---
def mat_05_kpk_dua(rng):
    a, b = rng.choice([(6, 8), (8, 12), (9, 12), (10, 15), (12, 18), (14, 21)])
    ans = math.lcm(a, b); g = math.gcd(a, b)
    cands = [a * b, g, ans + a, ans + b, ans // 2 if ans > 2 else ans + 4]
    return {"topic": "MAT-KPK", "subtopic": "KPK dua bilangan", "level": 1,
            "stem": f"Kelipatan Persekutuan Terkecil (KPK) dari {a} dan {b} adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Tentukan faktorisasi prima kedua bilangan lalu ambil faktor dengan pangkat terbesar.",
            "shortcut": "KPK = (a x b) / FPB(a, b)."}


def mat_06_fpb_dua(rng):
    g = rng.choice([4, 6, 8, 9, 12]); a = g * rng.choice([2, 3]); b = g * rng.choice([5, 7])
    ans = math.gcd(a, b)
    cands = [math.lcm(a, b), ans + 2, max(1, ans - 2), ans * 2, a]
    return {"topic": "MAT-KPK", "subtopic": "FPB dua bilangan", "level": 1,
            "stem": f"Faktor Persekutuan Terbesar (FPB) dari {a} dan {b} adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Ambil faktor prima yang sama dari kedua bilangan dengan pangkat terkecil.",
            "shortcut": "Cari pembagi terbesar yang habis membagi selisih kedua bilangan."}


def mat_07_kpk_jadwal(rng):
    a, b = rng.choice([(4, 6), (6, 9), (5, 8), (6, 10), (8, 12)])
    ans = math.lcm(a, b)
    cands = [a + b, a * b, ans + 2, max(1, ans - 2), ans + 4]
    return {"topic": "MAT-KPK", "subtopic": "Soal cerita KPK jadwal", "level": 2,
            "stem": f"Lampu A berkedip tiap {a} detik dan lampu B tiap {b} detik. Keduanya menyala bersama setiap ... detik.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Kejadian berulang bersamaan dihitung memakai KPK dari kedua interval waktu.",
            "shortcut": "Kata kunci 'bersamaan lagi' pada jadwal berulang selalu memakai KPK."}


def mat_08_fpb_bagi_rata(rng):
    g = rng.choice([5, 6, 8, 10]); a = g * rng.choice([3, 4]); b = g * rng.choice([5, 7])
    ans = math.gcd(a, b)
    cands = [a + b, ans * 2, max(1, ans - 2), math.lcm(a, b), ans + 3]
    return {"topic": "MAT-KPK", "subtopic": "Soal cerita FPB paket sama", "level": 3,
            "stem": f"Ibu memiliki {a} jeruk dan {b} apel untuk dibagikan ke beberapa bingkisan dengan isi sama banyak. Paling banyak dapat dibuat ... bingkisan.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Jumlah bingkisan terbanyak yang membagi habis kedua buah adalah FPB kedua bilangan.",
            "shortcut": "Kata kunci 'dibagi sama banyak/paling banyak' selalu memakai FPB."}


# --- MAT-PBD (4) ---
def mat_09_pbd_jumlah(rng):
    p, q = rng.choice([(2, 3), (3, 4), (3, 5), (4, 5)]); k = rng.randint(4, 10)
    tot = (p + q) * k; ans = p * k
    cands = [q * k, tot, ans + k, max(1, ans - k), p + q]
    return {"topic": "MAT-PBD", "subtopic": "Perbandingan diketahui jumlah", "level": 2,
            "stem": f"Perbandingan kelereng Andi dan Budi adalah {p} : {q}. Jika jumlah kelereng mereka {tot}, banyak kelereng Andi adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Nilai satu bagian adalah jumlah total dibagi jumlah angka perbandingan.",
            "shortcut": "Ditanya / (Jumlah perbandingan) x Total diketahui."}


def mat_10_pbd_selisih(rng):
    p, q = rng.choice([(2, 5), (3, 7), (4, 7), (5, 8)]); k = rng.randint(3, 9)
    diff = (q - p) * k; ans = q * k
    cands = [p * k, diff, ans + k, max(1, ans - k), (p + q) * k]
    return {"topic": "MAT-PBD", "subtopic": "Perbandingan diketahui selisih", "level": 2,
            "stem": f"Perbandingan umur adik dan kakak adalah {p} : {q}. Jika selisih umur mereka {diff} tahun, umur kakak adalah ... tahun.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Bagi selisih nyata dengan selisih perbandingan untuk memperoleh nilai satu unit.",
            "shortcut": "Ditanya / (Selisih perbandingan) x Selisih diketahui."}


def mat_11_pbd_skala_jarak(rng):
    skala_rb = rng.choice([200, 250, 500, 1000]); jp = rng.randint(3, 9)
    js_km = skala_rb * jp // 100
    if (skala_rb * jp) % 100 != 0:
        jp = rng.choice([4, 8]); js_km = skala_rb * jp // 100
    cands = [js_km * 10, max(1, js_km // 2), js_km + jp, js_km + 5, skala_rb // 10]
    return {"topic": "MAT-PBD", "subtopic": "Skala mencari jarak sebenarnya", "level": 2,
            "stem": f"Jarak dua kota pada peta berskala 1 : {skala_rb * 1000:,}".replace(",", ".") + f" adalah {jp} cm. Jarak sebenarnya adalah ... km.",
            "correct": str(js_km), "distractors": _pick_pos(js_km, cands, str),
            "explanation": "Kalikan jarak peta dengan faktor skala lalu ubah cm menjadi km dengan membagi 100.000.",
            "shortcut": "Hilangkan 5 nol pada skala terlebih dahulu sebelum dikali jarak peta."}


def mat_12_pbd_berbalik(rng):
    pekerja, hari, p2 = rng.choice([(6, 8, 4), (6, 10, 5), (8, 9, 12), (8, 6, 12), (10, 6, 15), (12, 5, 10), (9, 8, 12), (10, 9, 15)])
    total = pekerja * hari
    ans = total // p2
    cands = [ans + 2, max(1, ans - 2), hari * p2 // pekerja if (hari * p2) % pekerja == 0 else ans + 4, ans + 5, p2]
    return {"topic": "MAT-PBD", "subtopic": "Perbandingan berbalik nilai", "level": 3,
            "stem": f"Suatu pekerjaan selesai oleh {pekerja} pekerja dalam {hari} hari. Jika dikerjakan {p2} pekerja, waktu selesainya adalah ... hari.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Total beban kerja konstan, yaitu pekerja awal dikali hari awal, lalu dibagi jumlah pekerja baru.",
            "shortcut": "Berbalik nilai: kalikan pasangan awal, lalu bagi angka baru."}


# --- MAT-PSN (4) ---
def mat_13_psn_diskon(rng):
    harga = rng.choice([40, 60, 80, 120, 150]) * 1000; p = rng.choice([10, 20, 25, 50])
    bayar = harga * (100 - p) // 100; pot = harga * p // 100
    rp = lambda v: "Rp" + f"{v:,}".replace(",", ".")
    cands = [pot, harga + pot, harga - p * 100, bayar + 5000, max(1000, bayar - 5000)]
    return {"topic": "MAT-PSN", "subtopic": "Harga setelah diskon", "level": 2,
            "stem": f"Harga sebuah buku paket {rp(harga)} mendapat diskon {p}%. Harga yang harus dibayar adalah ...",
            "correct": rp(bayar), "distractors": _pick_pos(bayar, cands, rp),
            "explanation": "Hitung besar potongan (diskon% x harga) lalu kurangkan dari harga awal.",
            "shortcut": "Harga bayar = (100% - diskon%) x harga awal."}


def mat_14_psn_bagian(rng):
    tot = rng.choice([40, 50, 80, 100, 120]); p = rng.choice([15, 20, 25, 30, 40])
    ans = tot * p // 100
    cands = [tot - ans, ans + 5, max(1, ans - 4), p, tot // 2]
    return {"topic": "MAT-PSN", "subtopic": "Persentase dari jumlah siswa", "level": 1,
            "stem": f"Dari {tot} siswa kelas 6, sebanyak {p}% gemar olahraga renang. Banyak siswa yang gemar renang adalah ... orang.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Ubah persen menjadi per seratus lalu kalikan dengan jumlah seluruh siswa.",
            "shortcut": "Kalikan angkanya dulu, lalu bagi 100."}


def mat_15_psn_pecahan_ke_persen(rng):
    a, b = rng.choice([(1, 4), (3, 4), (2, 5), (3, 5), (4, 5), (7, 10), (9, 20), (3, 25)])
    ans = a * 100 // b
    cands = [ans + 5, max(1, ans - 5), ans + 10, a * 10, b * 2]
    return {"topic": "MAT-PSN", "subtopic": "Mengubah pecahan ke persen", "level": 1,
            "stem": f"Bentuk persen dari pecahan {a}/{b} adalah ...",
            "correct": f"{ans}%", "distractors": _pick_pos(ans, cands, lambda v: f"{v}%"),
            "explanation": "Kalikan pecahan dengan 100% untuk memperoleh nilai persennya.",
            "shortcut": "Bagi 100 oleh penyebutnya, lalu kalikan hasilnya dengan pembilang."}


def mat_16_psn_untung(rng):
    beli = rng.choice([50, 80, 100, 120]) * 1000; p = rng.choice([10, 20, 25])
    jual = beli * (100 + p) // 100
    rp = lambda v: "Rp" + f"{v:,}".replace(",", ".")
    cands = [beli * p // 100, beli - (beli * p // 100), jual + 5000, max(1000, jual - 5000), beli]
    return {"topic": "MAT-PSN", "subtopic": "Harga jual dan keuntungan", "level": 3,
            "stem": f"Seorang pedagang membeli barang seharga {rp(beli)} lalu menjualnya dengan keuntungan {p}%. Harga jual barang itu adalah ...",
            "correct": rp(jual), "distractors": _pick_pos(jual, cands, rp),
            "explanation": "Harga jual adalah harga beli ditambah persentase keuntungan terhadap harga beli.",
            "shortcut": "Harga jual = (100% + untung%) x harga beli."}


# --- MAT-BIL (4) ---
def mat_17_bil_campuran(rng):
    a = rng.randint(12, 30); b = rng.randint(3, 8); c = rng.randint(2, 6); d = rng.randint(5, 15)
    ans = a + b * c - d
    cands = [(a + b) * c - d, a + b * (c - d), ans + 4, max(1, ans - 3), ans + 10]
    return {"topic": "MAT-BIL", "subtopic": "Operasi hitung campuran", "level": 1,
            "stem": f"Hasil dari {a} + {b} x {c} - {d} adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Dahulukan perkalian sebelum penjumlahan dan pengurangan.",
            "shortcut": "Kerjakan kali/bagi terlebih dulu dari kiri ke kanan."}


def mat_18_bil_negatif(rng):
    t1 = rng.randint(-12, -2); naik = rng.randint(8, 18); turun = rng.randint(1, 5)
    ans = t1 + naik - turun
    cands = [t1 - naik - turun, abs(t1) + naik - turun, ans + 3, ans - 3, ans + 6]
    return {"topic": "MAT-BIL", "subtopic": "Bilangan bulat negatif suhu", "level": 2,
            "stem": f"Suhu awal lemari pendingin adalah {t1} C. Lalu suhunya naik {naik} C dan turun lagi {turun} C. Suhu akhirnya adalah ... C.",
            "correct": str(ans), "distractors": _pick(ans, cands, str),
            "explanation": "Suhu naik berarti ditambah, sedangkan suhu turun berarti dikurang.",
            "shortcut": "Hitung naik (+), turun (-), berurutan dari suhu awal."}


def mat_19_bil_kuadrat(rng):
    a = rng.randint(6, 15); b = rng.randint(3, 9)
    ans = a * a - b * b
    cands = [(a - b) * (a - b), a * 2 - b * 2, ans + 5, max(1, ans - 5), a * a + b * b]
    return {"topic": "MAT-BIL", "subtopic": "Bilangan pangkat dua", "level": 2,
            "stem": f"Nilai dari {a}^2 - {b}^2 adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Hitung kuadrat masing-masing bilangan lalu kurangkan hasilnya.",
            "shortcut": "Gunakan a^2 - b^2 = (a + b)(a - b) agar lebih cepat."}


def mat_20_bil_skor_tes(rng):
    benar = rng.randint(22, 32); salah = rng.randint(3, 8); kosong = 40 - benar - salah
    ans = benar * 4 - salah * 2 - kosong * 1
    cands = [benar * 4 - salah * 2, benar * 4 + salah * 2, ans + 4, max(1, ans - 4), benar * 4]
    return {"topic": "MAT-BIL", "subtopic": "Skor aturan benar salah kosong", "level": 3,
            "stem": f"Dalam lomba 40 soal, benar bernilai +4, salah -2, dan kosong -1. Jika Rina menjawab {benar} benar dan {salah} salah, total skornya adalah ...",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Cari jumlah soal kosong = 40 - benar - salah, lalu kalikan tiap jumlah dengan bobot nilainya.",
            "shortcut": "Jangan lupa hitung sisa soal kosong sebelum menjumlah poin."}


# --- MAT-GEO (4) ---
def mat_21_geo_luas_pp(rng):
    p = rng.randint(10, 24); l = rng.randint(4, p - 2); ans = p * l
    cands = [2 * (p + l), p + l, ans + p, max(1, ans - l), ans + 10]
    return {"topic": "MAT-GEO", "subtopic": "Luas persegi panjang", "level": 1,
            "stem": f"Sebuah lapangan berbentuk persegi panjang berukuran panjang {p} m dan lebar {l} m. Luasnya adalah ... m^2.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Luas persegi panjang dihitung dengan mengalikan panjang dan lebar.",
            "shortcut": "Luas = p x l; keliling = 2(p + l)."}


def mat_22_geo_luas_segitiga(rng):
    a = rng.choice([8, 10, 12, 14, 16, 18]); t = rng.randint(5, 13); ans = a * t // 2
    cands = [a * t, a + t, ans + a // 2, max(1, ans - 4), ans + 6]
    return {"topic": "MAT-GEO", "subtopic": "Luas segitiga", "level": 1,
            "stem": f"Sebuah segitiga memiliki alas {a} cm dan tinggi {t} cm. Luas segitiga tersebut adalah ... cm^2.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Luas segitiga sama dengan setengah dari hasil kali alas dan tingginya.",
            "shortcut": "Bagi dua angka genap (alas atau tinggi) dulu sebelum dikali."}


def mat_23_geo_volume_balok(rng):
    p = rng.randint(8, 15); l = rng.randint(4, 9); t = rng.randint(3, 7); ans = p * l * t
    cands = [2 * (p * l + p * t + l * t), p * l + t, ans + p * l, max(1, ans - l * t), ans + 12]
    return {"topic": "MAT-GEO", "subtopic": "Volume balok", "level": 2,
            "stem": f"Akuarium berbentuk balok memiliki panjang {p} dm, lebar {l} dm, dan tinggi {t} dm. Volume maksimalnya adalah ... liter.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "1 dm^3 sama dengan 1 liter, sehingga volume dalam liter sama dengan p x l x t.",
            "shortcut": "1 dm^3 = 1 liter, langsung kalikan p x l x t."}


def mat_24_geo_keliling_lingkaran(rng):
    r = rng.choice([7, 14, 21, 28]); ans = 2 * 22 * r // 7
    cands = [22 * r // 7, 22 * r * r // 7, ans + 22, max(1, ans - 11), ans + 14]
    return {"topic": "MAT-GEO", "subtopic": "Keliling lingkaran kelipatan 7", "level": 2,
            "stem": f"Sebuah taman berbentuk lingkaran berjari-jari {r} m (pi = 22/7). Keliling taman tersebut adalah ... m.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Keliling lingkaran = 2 x pi x r dengan pi = 22/7.",
            "shortcut": "Keliling = 2 x 22/7 x r; bagi r dengan 7 dulu."}


# --- MAT-SAT (4) ---
def mat_25_sat_panjang(rng):
    km = rng.randint(2, 9); m = rng.choice([250, 400, 500, 750])
    ans = km * 1000 + m
    cands = [km * 100 + m, km * 1000 + m * 10, ans + 500, max(100, ans - 500), km + m]
    return {"topic": "MAT-SAT", "subtopic": "Konversi satuan panjang", "level": 1,
            "stem": f"Jarak rumah ke sekolah adalah {km} km lebih {m} m. Jika dinyatakan dalam meter menjadi ... m.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "1 km sama dengan 1.000 meter, lalu tambahkan sisa meternya.",
            "shortcut": "1 km = 1.000 m, tinggal tambahkan tiga nol di belakang km."}


def mat_26_sat_waktu(rng):
    j = rng.randint(2, 5); m = rng.choice([15, 20, 30, 45]); ans = j * 60 + m
    cands = [j * 100 + m, j * 60 - m, ans + 30, max(10, ans - 30), j * 360 + m]
    return {"topic": "MAT-SAT", "subtopic": "Konversi jam ke menit", "level": 1,
            "stem": f"Lama perjalanan kereta adalah {j} jam {m} menit. Lama perjalanan tersebut sama dengan ... menit.",
            "correct": str(ans), "distractors": _pick_pos(ans, cands, str),
            "explanation": "Setiap 1 jam setara dengan 60 menit, lalu tambahkan sisa menitnya.",
            "shortcut": "Jam x 60 + sisa menit."}


def mat_27_sat_berat(rng):
    ton = rng.randint(1, 4); kw = rng.randint(2, 8); ans = ton * 1000 + kw * 100
